from pathlib import Path
import json,hashlib
import numpy as np,pandas as pd
R=Path(__file__).resolve().parent;S=Path('/workspace/codex/results/TCGA_LIHC_candidate30_survival')
protocol=json.loads((S/'protocol.json').read_text());protocol['task']='Add PGAM5 to previously fixed30 candidate genes and rerun31-gene survival analysis';protocol['score']=protocol['score'].replace('30','31');protocol['comparison']='Compare fixed30 and31 gene equal-weight scores, each global outcome-blind median split; no new cutpoint search or gene selection';protocol['reuse']='Identical371 patients, raw31-gene counts and whole-library denominators, clinical source and endpoint eligibility to30-gene run';(R/'protocol.json').write_text(json.dumps(protocol,indent=2))
genes=pd.read_csv(S/'signature_30_genes.csv').gene.tolist()+['PGAM5'];assert len(set(genes))==31;pd.DataFrame({'gene':genes,'weight':1/31}).to_csv(R/'signature_31_genes.csv',index=False)
old=pd.read_csv(S/'patient_scores_survival_join.csv');raw=pd.read_csv(S/'selected_patient_31_gene_counts.csv',index_col=0);assert set(old.patient)==set(raw.index);raw=raw.loc[old.patient];X=np.log2(raw[genes].div(old.set_index('patient').assigned_gene_counts,axis=0)*1e6+1);mean=X.mean();sd=X.std(ddof=1);assert (sd>0).all();z=(X-mean)/sd;score=z.mean(axis=1);cut=float(score.median());df=old.copy();df=df.rename(columns={'candidate30_score':'previous30_score','group':'previous30_group'});df['candidate31_score']=score.to_numpy();df['group']=np.where(df.candidate31_score>cut,'High','Low');df.to_csv(R/'patient_scores_survival_join.csv',index=False);df[['patient','RNA_sample','candidate31_score','group','PGAM5_log2_CPM_plus1','assigned_gene_counts']].to_csv(R/'patient_scores.csv',index=False);df[['patient','previous30_score','previous30_group','candidate31_score','group']].to_csv(R/'30_vs_31_patient_comparison.csv',index=False);raw.to_csv(R/'selected_patient_31_gene_counts.csv');X.to_csv(R/'selected_patient_log2_CPM_plus1.csv');z.to_csv(R/'selected_patient_31_gene_zscores.csv');pd.DataFrame({'gene':genes,'bulk_training_mean_log2_CPM_plus1':mean.loc[genes].to_numpy(),'bulk_training_SD':sd.loc[genes].to_numpy(),'weight':1/31}).to_csv(R/'bulk_score_parameters.csv',index=False)
pg=(X.PGAM5-X.PGAM5.mean())/X.PGAM5.std(ddof=1);expected=(30*df.previous30_score.to_numpy()+pg.to_numpy())/31;err=float(abs(expected-score.to_numpy()).max());assert err<1e-12;assert df.patient.is_unique and len(df)==371
summary=json.loads((S/'preparation_summary.json').read_text());summary.pop('30_signature_genes_present',None);summary.update({'31_signature_genes_present':True,'score_median':cut,'high_patients':int(df.group.eq('High').sum()),'low_patients':int(df.group.eq('Low').sum()),'changed_group_vs_30':int(df.group.ne(df.previous30_group).sum()),'score_identity_max_error':err});(R/'preparation_summary.json').write_text(json.dumps(summary,indent=2))
(R/'source_provenance.json').write_text(json.dumps({'parent_results':'results/TCGA_LIHC_candidate30_survival','parent_commit':'ea9814123612d42527dbb0b613e1f7e1075764f7','parent_provenance':json.loads((S/'source_provenance.json').read_text()),'input_hashes':{p.name:hashlib.sha256(p.read_bytes()).hexdigest() for p in [S/'patient_scores_survival_join.csv',S/'selected_patient_31_gene_counts.csv',S/'signature_30_genes.csv']}},indent=2));print(json.dumps(summary,indent=2))
